    "path": "package.json",
    "content": "{\n  \"name\": \"exfrozen-study-bot\",\n  \"private\": true,\n  \"devDependencies\": {\n    \"@tgcloud/cli\": \"^0.2.0\"\n  },\n  \"scripts\": {\n    \"postinstall\": \"node scripts/patch-tgcloud-cli.js\",\n    \"deploy\": \"tgcloud push\",\n    \"status\": \"tgcloud status\",\n    \"run\": \"tgcloud run\",\n    \"test\": \"node --test test/**/*.test.js\",\n    \"validate\": \"node scripts/validate.js && npm test\",\n    \"generate:snapshot\": \"node scripts/generate_snapshot.js\"\n  },\n  \"type\": \"module\"\n}\n"
